const { addInstanceMethod } = require('../../../../src/plugins/instance/main.js');

describe('addInstanceMethod', () => {
  let ErrorClass;
  let methodName;
  let methodFunc;
  let plugin;
  let plugins;

  beforeEach(() => {
    ErrorClass = function(message) {
      this.message = message;
    };
    methodName = 'customMethod';
    methodFunc = function() {
      return this.message;
    };
    plugin = {};
    plugins = [];
  });

  test('should add instance method to ErrorClass prototype', () => {
    addInstanceMethod(plugin, plugins, ErrorClass, methodName, methodFunc);
    const errorInstance = new ErrorClass('Test message');
    expect(errorInstance[methodName]()).toBe('Test message');
  });

  test('should add static method to ErrorClass', () => {
    addInstanceMethod(plugin, plugins, ErrorClass, methodName, methodFunc);
    expect(ErrorClass[methodName]).toBeDefined();
    expect(ErrorClass[methodName]()).toBeUndefined();
  });

  test('should not enumerate added methods', () => {
    addInstanceMethod(plugin, plugins, ErrorClass, methodName, methodFunc);
    const errorInstance = new ErrorClass('Test message');
    expect(Object.keys(errorInstance)).not.toContain(methodName);
    expect(Object.keys(ErrorClass)).not.toContain(methodName);
  });

  test('should throw TypeError if ErrorClass is not a function', () => {
    expect(() => addInstanceMethod(plugin, plugins, {}, methodName, methodFunc)).toThrow(TypeError);
  });

  test('should throw TypeError if methodName is not a string', () => {
    expect(() => addInstanceMethod(plugin, plugins, ErrorClass, {}, methodFunc)).toThrow(TypeError);
  });

  test('should throw TypeError if methodFunc is not a function', () => {
    expect(() => addInstanceMethod(plugin, plugins, ErrorClass, methodName, {})).toThrow(TypeError);
  });
});

