const { validatePluginName } = require('../../../../src/plugins/shape/name');

describe('validatePluginName', () => {
  const prefix = 'modern-errors-';

  it('should throw TypeError if plugin is null', () => {
    expect(() => validatePluginName(null)).toThrow(TypeError);
  });

  it('should throw TypeError if plugin is not an object', () => {
    expect(() => validatePluginName('not-an-object')).toThrow(TypeError);
  });

  it('should throw TypeError if plugin does not have a name property', () => {
    const plugin = {};
    expect(() => validatePluginName(plugin)).toThrow(TypeError);
  });

  it('should throw TypeError if name property is not a string', () => {
    const plugin = { name: 123 };
    expect(() => validatePluginName(plugin)).toThrow(TypeError);
  });

  it('should return a new plugin object with fullName property if name is valid', () => {
    const plugin = { name: 'example' };
    const result = validatePluginName(plugin);
    expect(result).toEqual({ ...plugin, fullName: `${prefix}example` });
  });

  it('should not modify the original plugin object', () => {
    const plugin = { name: 'example' };
    const originalPlugin = { ...plugin };
    validatePluginName(plugin);
    expect(plugin).toEqual(originalPlugin);
  });

  it('should append prefix to the name in fullName property', () => {
    const plugin = { name: 'example' };
    const result = validatePluginName(plugin);
    expect(result.fullName).toBe(`${prefix}example`);
  });
});

