const { deepCloneObject } = require('../../../src/options/clone.js');

describe('deepCloneObject', () => {
  test('should return a deep clone of a simple object', () => {
    const obj = { a: 1, b: 2 };
    const clonedObj = deepCloneObject(obj);
    expect(clonedObj).toEqual(obj);
    expect(clonedObj).not.toBe(obj);
  });

  test('should return a deep clone of a nested object', () => {
    const obj = { a: { b: { c: 3 } } };
    const clonedObj = deepCloneObject(obj);
    expect(clonedObj).toEqual(obj);
    expect(clonedObj).not.toBe(obj);
    expect(clonedObj.a).not.toBe(obj.a);
    expect(clonedObj.a.b).not.toBe(obj.a.b);
  });

  test('should preserve property descriptors', () => {
    const obj = {};
    Object.defineProperty(obj, 'a', {
      value: 1,
      writable: false,
      enumerable: false,
      configurable: false
    });
    const clonedObj = deepCloneObject(obj);
    const descriptor = Object.getOwnPropertyDescriptor(clonedObj, 'a');
    expect(descriptor).toMatchObject({
      value: 1,
      writable: false,
      enumerable: false,
      configurable: false
    });
  });

  test('should handle objects with arrays', () => {
    const obj = { a: [1, 2, 3] };
    const clonedObj = deepCloneObject(obj);
    expect(clonedObj).toEqual(obj);
    expect(clonedObj.a).not.toBe(obj.a);
  });

  test('should throw TypeError if input is not an object', () => {
    expect(() => deepCloneObject(null)).toThrow(TypeError);
    expect(() => deepCloneObject(42)).toThrow(TypeError);
    expect(() => deepCloneObject('string')).toThrow(TypeError);
  });

  test('should throw TypeError for non-cloneable properties', () => {
    const obj = { a: () => {} };
    expect(() => deepCloneObject(obj)).toThrow(TypeError);
  });

  test('should handle objects with symbol properties', () => {
    const sym = Symbol('a');
    const obj = { [sym]: 1 };
    const clonedObj = deepCloneObject(obj);
    expect(clonedObj[sym]).toBe(1);
    expect(clonedObj).not.toBe(obj);
  });

  test('should handle objects with circular references', () => {
    const obj = {};
    obj.self = obj;
    expect(() => deepCloneObject(obj)).toThrow(TypeError);
  });
});

