const lastArgIsOptions = require('../../../src/options/method').lastArgIsOptions;

describe('lastArgIsOptions', () => {
  it('should return true when last argument is an options object', () => {
    const isOptions = jest.fn().mockReturnValue(true);
    const fullName = 'TestPlugin';
    const lastArg = { option: true };

    const result = lastArgIsOptions({ isOptions, fullName }, lastArg);

    expect(result).toBe(true);
    expect(isOptions).toHaveBeenCalledWith(lastArg);
  });

  it('should return false when last argument is not an options object', () => {
    const isOptions = jest.fn().mockReturnValue(false);
    const fullName = 'TestPlugin';
    const lastArg = 'notAnOptionsObject';

    const result = lastArgIsOptions({ isOptions, fullName }, lastArg);

    expect(result).toBe(false);
    expect(isOptions).toHaveBeenCalledWith(lastArg);
  });

  it('should throw TypeError when isOptions does not return a boolean', () => {
    const isOptions = jest.fn().mockReturnValue('notABoolean');
    const fullName = 'TestPlugin';
    const lastArg = { option: true };

    expect(() => {
      lastArgIsOptions({ isOptions, fullName }, lastArg);
    }).toThrow(TypeError);
  });

  it('should throw TypeError with correct error message when isOptions does not return a boolean', () => {
    const isOptions = jest.fn().mockReturnValue('notABoolean');
    const fullName = 'TestPlugin';
    const lastArg = { option: true };

    expect(() => {
      lastArgIsOptions({ isOptions, fullName }, lastArg);
    }).toThrow(`Expected isOptions to return a boolean for TestPlugin`);
  });

  it('should not modify the input arguments', () => {
    const isOptions = jest.fn().mockReturnValue(true);
    const fullName = 'TestPlugin';
    const lastArg = { option: true };

    const originalArgs = { isOptions, fullName };
    const originalLastArg = { ...lastArg };

    lastArgIsOptions(originalArgs, lastArg);

    expect(originalArgs).toEqual({ isOptions, fullName });
    expect(lastArg).toEqual(originalLastArg);
  });
});

